301	    /**
302	     * The owner's numeric membership level, derived on read from {@link #getMembershipPoints()}:
303	     * level 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and 4 for 6 or more; then held down to the owner's
304	     * {@link #getMembershipLevelCap() membership level cap} when one has been assigned.
305	     */
306	    @Transient
