381	    /** The membership {@code level} held down to {@code cap}, i.e. the smaller of the two, when a cap
382	     *  is present; the level unchanged when {@code cap} is {@code null} and no ceiling applies. */
383	    private static int capMembershipLevel(int level, Integer cap) {
384	        return cap == null ? level : Math.min(level, cap);
385	    }
