477	    private static final Map<String, String> REGION_TIMEZONES = Map.of(
478	        "NSW", "Australia/Sydney",
479	        "VIC", "Australia/Melbourne",
480	        "QLD", "Australia/Brisbane");
481	
482	    /**
483	     * The owner's timezone, derived on read as the IANA name for the owner's
484	     * {@link #getLocality() locality/region} via the fixed region-to-timezone table
485	     * ({@code NSW -> Australia/Sydney}, {@code VIC -> Australia/Melbourne},
486	     * {@code QLD -> Australia/Brisbane}). Returns {@code null} when the region carries no entry in
487	     * the table (e.g. {@code UNKNOWN}).
488	     */
489	    @Transient
490	    public String getTimezone() {
491	        return timezoneForRegion(getLocality());
492	    }
493	
494	    /** The IANA timezone name for {@code region} via the fixed region-to-timezone table, or
495	     *  {@code null} when the region carries no entry ({@code NSW -> Australia/Sydney},
496	     *  {@code VIC -> Australia/Melbourne}, {@code QLD -> Australia/Brisbane}). */
497	    public static String timezoneForRegion(String region) {
498	        return REGION_TIMEZONES.get(region);
499	    }
500	
501	    /** The inclusive 4-digit postcode {@code {low, high}} range for {@code region}, or {@code null} when
502	     *  the region carries no range rule (i.e. {@code UNKNOWN} or any region absent from the table:
503	     *  {@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). */
504	    public static int[] postcodeRangeForRegion(String region) {
505	        return REGION_POSTCODE_RANGES.get(region);
506	    }
507	
508	    /** The region whose postcode range contains {@code postcode}, or {@code null} when the postcode is
509	     *  absent, not a 4-digit value, or in no known range. */
510	    private static String regionForPostcode(String postcode) {
511	        if (postcode == null || !postcode.matches("^[0-9]{4}$")) {
512	            return null;
513	        }
514	        int value = Integer.parseInt(postcode);
515	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
516	            int[] range = entry.getValue();
517	            if (value >= range[0] && value <= range[1]) {
518	                return entry.getKey();
519	            }
520	        }
521	        return null;
522	    }
523	
524	    /** Telephone country code -> the national-number length it requires ({@code +61} Australia => 9
525	     *  digits, {@code +1} NANP => 10), used to derive telephone values from the stored E.164 number.
526	     *  The country codes here carry no conflicting prefixes ({@code +61} does not start with
527	     *  {@code +1}), so a number matches at most one. */
528	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = Map.of(
529	        "+61", 9, "+1", 10);
530	
531	    /**
532	     * The stored E.164 {@link #telephone} formatted for humans, derived on read: the country code, a
533	     * space, then the national digits grouped in threes (e.g. {@code "+61 412 345 678"}). Falls back
534	     * to the raw value when it is {@code null} or begins with no recognised country code.
535	     */
536	    @Transient
537	    public String getTelephoneDisplay() {
538	        if (this.telephone == null) {
539	            return null;
540	        }
541	        String countryCode = countryCodeOf(this.telephone);
542	        if (countryCode == null) {
543	            return this.telephone;
544	        }
545	        String national = this.telephone.substring(countryCode.length());
546	        StringBuilder grouped = new StringBuilder(countryCode);
547	        for (int i = 0; i < national.length(); i++) {
548	            if (i % 3 == 0) {
549	                grouped.append(' ');
550	            }
551	            grouped.append(national.charAt(i));
552	        }
553	        return grouped.toString();
554	    }
555	
556	    /** The recognised telephone country code that {@code telephone} begins with (e.g. {@code "+61"}),
557	     *  or {@code null} when it is {@code null} or begins with no recognised country code. */
558	    public static String countryCodeOf(String telephone) {
559	        if (telephone == null) {
560	            return null;
561	        }
562	        for (String countryCode : NATIONAL_NUMBER_LENGTHS.keySet()) {
563	            if (telephone.startsWith(countryCode)) {
564	                return countryCode;
565	            }
566	        }
567	        return null;
568	    }
569	
570	    /** The national-number length required for {@code countryCode}, or {@code null} when the country
571	     *  code carries no length rule (i.e. any code absent from the table: {@code +61 => 9},
572	     *  {@code +1 => 10}). */
573	    public static Integer nationalNumberLength(String countryCode) {
574	        return NATIONAL_NUMBER_LENGTHS.get(countryCode);
575	    }
576	
577	    /** The single Luhn check digit (0-9) over the decimal digits contained in {@code value}, scanning
578	     *  right to left and doubling every second digit; non-digit characters are ignored and a null or
579	     *  digit-free value yields {@code 0}. */
580	    private static int luhnCheckDigit(String value) {
581	        int sum = 0;
582	        boolean doubling = true;
583	        for (int i = (value == null ? 0 : value.length()) - 1; i >= 0; i--) {
584	            char c = value.charAt(i);
585	            if (c < '0' || c > '9') {
586	                continue;
587	            }
588	            int digit = c - '0';
589	            if (doubling) {
590	                digit *= 2;
591	                if (digit > 9) {
592	                    digit -= 9;
593	                }
594	            }
595	            sum += digit;
596	            doubling = !doubling;
597	        }
598	        return (10 - (sum % 10)) % 10;
599	    }
600	
601	    protected Set<Pet> getPetsInternal() {
602	        if (this.pets == null) {
603	            this.pets = new HashSet<>();
604	        }
605	        return this.pets;
606	    }
607	
608	    protected void setPetsInternal(Set<Pet> pets) {
609	        this.pets = pets;
610	    }
611	
612	    public List<Pet> getPets() {
613	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
614	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
615	        return Collections.unmodifiableList(sortedPets);
616	    }
617	
618	    public void setPets(List<Pet> pets) {
619	        this.pets = new HashSet<>(pets);
620	    }
621	
622	    public void addPet(Pet pet) {
623	        getPetsInternal().add(pet);
624	        pet.setOwner(this);
625	    }
626	
627	    /**
628	     * Return the Pet with the given name, or null if none found for this Owner.
629	     *
630	     * @param name to test
631	     * @return true if pet name is already in use
632	     */
633	    public Pet getPet(String name) {
634	        return getPet(name, false);
635	    }
636	
637	    /**
638	     * Return the Pet with the given name, or null if none found for this Owner.
639	     *
640	     * @param name to test
641	     * @return true if pet name is already in use
642	     */
643	    public Pet getPet(String name, boolean ignoreNew) {
644	        name = name.toLowerCase();
645	        for (Pet pet : getPetsInternal()) {
646	            if (!ignoreNew || !pet.isNew()) {
647	                String compName = pet.getName();
648	                compName = compName.toLowerCase();
649	                if (compName.equals(name)) {
650	                    return pet;
651	                }
652	            }
653	        }
654	        return null;
655	    }
656	
657	    public Pet getPet(Integer petId) {
658	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
659	    }
660	
661	    @Override
662	    public String toString() {
663	        return new ToStringCreator(this)
664	
665	            .append("id", this.getId())
666	            .append("new", this.isNew())
667	            .append("lastName", this.getLastName())
668	            .append("firstName", this.getFirstName())
669	            .append("address", this.address)
670	            .append("city", this.city)
671	            .append("telephone", this.telephone)
672	            .toString();
673	    }
674	}
