416	    /** Matches a well-formed postcode: exactly 4 digits. */
417	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("^[0-9]{4}$");
418	
419	    /**
420	     * Whether {@code owner}'s postcode is acceptable. Postcode is optional: a null postcode is always
421	     * accepted. When present it must be a 4-digit value and, when the owner's city maps to a known
422	     * region, must fall within that region's inclusive range (NSW 2000-2099, VIC 3000-3099,
423	     * QLD 4000-4099); a city with no known region accepts any 4-digit postcode. The region-to-range
424	     * table lives on {@link Owner#postcodeRangeForRegion(String)} and is shared, not duplicated here.
425	     */
426	    private static boolean isPostcodeValidForCity(Owner owner) {
427	        String postcode = owner.getPostcode();
428	        if (postcode == null) {
429	            return true;
430	        }
431	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
432	            return false;
433	        }
434	        int[] range = Owner.postcodeRangeForRegion(owner.getRegion());
435	        if (range == null) {
436	            return true;
437	        }
438	        int value = Integer.parseInt(postcode);
439	        return value >= range[0] && value <= range[1];
440	    }
441	
442	    /** Matches a well-formed E.164 number: a '+' followed by 8 to 15 digits. */
443	    private static final Pattern E164_PATTERN = Pattern.compile("^\\+[0-9]{8,15}$");
444	
445	    /**
446	     * Canonical stored form of a telephone number in E.164: a leading '+' and country
447	     * code are kept when present; otherwise country code '+61' is assumed and a single
448	     * leading '0' is dropped from the national digits. Spaces, dashes and brackets are
449	     * stripped. The result must be a '+' followed by 8 to 15 digits, and its national number
450	     * must have the length required for its country code ('+61' => 9 digits, '+1' => 10).
451	     * Returns {@code null} when the number cannot form a valid E.164 value.
452	     */
453	    private static String normalizeTelephone(String telephone) {
454	        if (telephone == null) {
455	            return null;
456	        }
457	        String cleaned = telephone.replaceAll("[\\s()\\[\\]-]", "");
458	        String e164;
459	        if (cleaned.startsWith("+")) {
460	            e164 = cleaned;
461	        } else {
462	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
463	            e164 = "+61" + national;
464	        }
465	        if (!E164_PATTERN.matcher(e164).matches()) {
466	            return null;
467	        }
468	        return hasValidNationalNumberLength(e164) ? e164 : null;
469	    }
470	
471	    /**
472	     * Whether the national number of a well-formed E.164 value has the length required for its
473	     * country code. The country-code length table lives on {@link Owner#nationalNumberLength(String)}
474	     * and is shared, not duplicated here; a country code carrying no length rule is accepted.
475	     */
476	    private static boolean hasValidNationalNumberLength(String e164) {
477	        String countryCode = Owner.countryCodeOf(e164);
478	        if (countryCode == null) {
479	            return true;
480	        }
481	        return e164.length() - countryCode.length() == Owner.nationalNumberLength(countryCode);
482	    }
