484	    /**
485	     * Compute and assign the derived attributes carried by a newly registered owner: the customer
486	     * code, membership number, household id, namesake count and household member count. Each is
487	     * derived from the owner's already-normalized fields and the existing owner population, so this
488	     * must run before the owner is saved, while the counts still exclude the owner being created.
489	     *
490	     * <p>{@code declaredMember} is true when the owner was created into an existing household by
491	     * setting {@code sharesHousehold}: such an owner is a declared, not a suspected, household member,
492	     * so it is never flagged as a possible duplicate; otherwise the usual possible-duplicate check
493	     * runs (and, since a create that reaches here shares no existing household, does not flag it).
494	     */
495	    private void assignRegistrationAttributes(Owner owner, boolean declaredMember) {
496	        owner.setCustomerCode(generateCustomerCode(owner));
497	        owner.setMembershipNumber(generateMembershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
498	        owner.setHouseholdId(householdId(owner));
499	        owner.setNamesakeCount(countNamesakes(owner));
500	        owner.setHouseholdMemberCount(countHouseholdMembers(owner));
501	        if (declaredMember) {
502	            owner.setPossibleDuplicate(false);
503	            owner.setPossibleDuplicateOf(null);
504	        } else {
505	            assignPossibleDuplicate(owner);
506	        }
507	    }
508	
509	    /**
510	     * Whether {@code owner} would join an existing household, i.e. some already-registered owner
511	     * resolves to the same {@link #householdId(Owner) householdId} (same last name and postcode).
512	     * Because the household is keyed on (last name, postcode), such a create is a household duplicate
513	     * and is rejected with {@code 409 CONFLICT} unless the request sets {@code sharesHousehold}, in
514	     * which case the owner is created as a declared household member.
515	     */
516	    private boolean hasExistingHousehold(Owner owner) {
517	        return !findHousemates(owner).isEmpty();
518	    }
519	
520	    /**
521	     * Flag {@code owner} as a possible duplicate when, though not a hard duplicate (its create having
522	     * already cleared the {@link #isDuplicate} identity gate), it shares an existing owner's last name
523	     * (compared case-insensitively with collapsed whitespace) and postcode but carries a different
524	     * telephone. Sets {@code possibleDuplicate} accordingly and, when true, {@code possibleDuplicateOf}
525	     * to the matching owner's id. Runs before save, against the existing owner population.
526	     */
527	    private void assignPossibleDuplicate(Owner owner) {
528	        Integer matchId = findPossibleDuplicateOf(owner);
529	        owner.setPossibleDuplicate(matchId != null);
530	        owner.setPossibleDuplicateOf(matchId);
531	    }
532	
533	    /**
534	     * The id of an existing owner that shares {@code owner}'s postcode and last name (compared
535	     * case-insensitively with collapsed whitespace) but has a different telephone, or {@code null}
536	     * when there is none. When several match, the lowest id is returned. An owner without a postcode
537	     * never matches.
538	     */
539	    private Integer findPossibleDuplicateOf(Owner owner) {
540	        String postcode = owner.getPostcode();
541	        if (postcode == null) {
542	            return null;
543	        }
544	        String lastName = normalizeHouseholdField(owner.getLastName());
545	        String telephone = owner.getTelephone();
546	        return this.clinicService.findAllOwners().stream()
547	            .filter(existing -> !existing.isDeleted())
548	            .filter(existing -> existing.getId() != null
549	                && postcode.equals(existing.getPostcode())
550	                && normalizeHouseholdField(existing.getLastName()).equals(lastName)
551	                && !telephone.equals(existing.getTelephone()))
552	            .map(Owner::getId)
553	            .min(Integer::compareTo)
554	            .orElse(null);
555	    }
556	
557	    /**
558	     * Build {@code owner}'s customer code '<REGION>-<HASH8>': REGION is the region code derived from
559	     * the owner's postcode ({@link Owner#getRegion()}) and HASH8 the first 8 upper-case hex
560	     * characters of SHA-256 over the owner's already-normalized telephone concatenated with the
561	     * owner's last name (e.g. 'NSW-1A2B3C4D'). The identity is otherwise a pure function of the
562	     * region and the (telephone, last name) pair; only when the computed code collides with an
563	     * existing owner's customer code is it de-duplicated by appending '-<n>' with the smallest
564	     * {@code n} of 2 or more that makes it unique (e.g. 'NSW-1A2B3C4D-2').
565	     */
566	    private String generateCustomerCode(Owner owner) {
567	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
568	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
569	        String hash8 = sha256Hex(telephone + lastName).substring(0, 8);
570	        String base = owner.getRegion() + "-" + hash8;
571	        return deduplicateCustomerCode(base);
572	    }
573	
574	    /**
575	     * De-duplicate a computed customer code against the existing owner population: when {@code base}
576	     * is not already in use it is returned unchanged; otherwise '-<n>' is appended with the smallest
577	     * {@code n} of 2 or more that yields a code no existing owner carries.
578	     */
579	    private String deduplicateCustomerCode(String base) {
580	        Set<String> existing = this.clinicService.findAllOwners().stream()
581	            .map(Owner::getCustomerCode)
582	            .filter(code -> code != null)
583	            .collect(java.util.stream.Collectors.toSet());
584	        if (!existing.contains(base)) {
585	            return base;
586	        }
587	        int n = 2;
588	        while (existing.contains(base + "-" + n)) {
589	            n++;
590	        }
591	        return base + "-" + n;
592	    }
