594	    /**
595	     * The number of existing owners registered in {@code city}, compared case-insensitively
596	     * with collapsed whitespace.
597	     */
598	    private int countOwnersInCity(String city) {
599	        String normalized = normalizeHouseholdField(city);
600	        return (int) this.clinicService.findAllOwners().stream()
601	            .filter(existing -> normalizeHouseholdField(existing.getCity()).equals(normalized))
