605	    /**
606	     * The effective registration date to store for a new owner: the date supplied on the request
607	     * when present, otherwise the current server date, in either case rolled forward to a business
608	     * day so it never falls on a weekend or public holiday (rolled forward to the next such day).
609	     * This single point of resolution is what every registration-date-derived value (the stored
610	     * date, the membership number's year segment, the per-day create-limit) is computed from.
611	     */
612	    private static LocalDate resolveRegistrationDate(LocalDate suppliedDate) {
613	        LocalDate date = suppliedDate != null ? suppliedDate : LocalDate.now();
614	        return toBusinessDay(date);
615	    }
616	
617	    /**
618	     * The fixed list of public holidays that a registration date must not fall on. A date landing
619	     * on one of these is rolled forward, exactly as weekends are.
620	     */
621	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
622	        LocalDate.of(2026, 1, 1),
623	        LocalDate.of(2026, 1, 26),
624	        LocalDate.of(2026, 4, 25),
625	        LocalDate.of(2026, 12, 25),
626	        LocalDate.of(2026, 12, 28));
627	
628	    /**
629	     * Roll {@code date} forward to the next business day: a Saturday, Sunday, or listed public
630	     * holiday is advanced day by day until it lands on a non-holiday weekday, which is returned
631	     * unchanged.
632	     */
633	    private static LocalDate toBusinessDay(LocalDate date) {
634	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY
635	                || PUBLIC_HOLIDAYS.contains(date)) {
636	            date = date.plusDays(1);
637	        }
638	        return date;
639	    }
640	
641	    /**
642	     * Build the membership number '<customerCode>-M<YY>' where YY is the
643	     * {@link #membershipYearSegment(LocalDate) fiscal-year segment} of the {@code registrationDate}
644	     * (e.g. 'NSW-1A2B3C4D-M27').
645	     */
646	    private static String generateMembershipNumber(String customerCode, LocalDate registrationDate) {
647	        return customerCode + "-M" + membershipYearSegment(registrationDate);
648	    }
649	
650	    /**
651	     * The two-digit year segment stamped into a membership number: the last two digits of the
652	     * fiscal year (starting 1 July) that contains the business-day-adjusted {@code registrationDate},
653	     * zero-padded (e.g. a date of 2026-09-05 falls in fiscal year 2027 -> '27'). Shares the
654	     * fiscal-year rule with {@link Owner#getFiscalYear()} via {@link Owner#fiscalYear(LocalDate)}.
655	     */
656	    private static String membershipYearSegment(LocalDate registrationDate) {
657	        return String.format("%02d", Owner.fiscalYear(registrationDate) % 100);
658	    }
