673	    /**
674	     * Whether more than 80 owners have already been created today, i.e. carry today's (business-day
675	     * resolved) registration date. Surfaced on responses as {@code bulkSignupWarning} to flag an
676	     * unusually high daily signup volume.
677	     */
678	    private boolean isBulkSignupWarning() {
679	        return countOwnersRegisteredOn(toBusinessDay(LocalDate.now())) > 80;
