689	    /**
690	     * The single derived key all duplicate detection flows through, formed from the owner's
691	     * already-normalized fields as {@code normalizedTelephone + '|' + (email or empty) + '|' +
692	     * (householdId or empty)}. It is computed at the create-time identity gate, before the household
693	     * id is derived, so the household segment is empty at that point. Because the telephone is part
694	     * of the key, two owners in the same household with different telephones resolve to different
695	     * keys and are both allowed.
696	     */
697	    private static String identityKey(Owner owner) {
698	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
699	        String email = owner.getEmail() == null ? "" : owner.getEmail();
700	        String household = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
701	        return telephone + "|" + email + "|" + household;
702	    }
703	
704	    /**
705	     * Whether {@code owner}'s whole {@link #identityKey} equals an existing owner's, which is the sole
706	     * duplicate condition: the previously separate telephone, email and household checks are now all
707	     * expressed through this one key, so only an exact full-key match is a duplicate and a create that
708	     * trips it is rejected with {@code 409 CONFLICT}.
709	     */
710	    private boolean isDuplicate(Owner owner) {
711	        String key = owner.getIdentityKey();
712	        return this.clinicService.findAllOwners().stream()
713	            .filter(existing -> !existing.isDeleted())
714	            .map(Owner::getIdentityKey)
715	            .filter(existing -> existing != null)
716	            .anyMatch(key::equals);
717	    }
