758	    /**
759	     * Existing owners that share {@code owner}'s household, i.e. resolve to the same
760	     * {@link #householdId(Owner) householdId}. Household membership is defined by that single derived
761	     * key rather than re-derived from the underlying fields here, so the household is described in one
762	     * place and every household-keyed value stays consistent with it.
763	     */
764	    private List<Owner> findHousemates(Owner owner) {
765	        String householdId = householdId(owner);
766	        return this.clinicService.findAllOwners().stream()
767	            .filter(existing -> !existing.isDeleted())
768	            .filter(existing -> householdId(existing).equals(householdId))
769	            .toList();
770	    }
