772	    /**
773	     * The number of owners in {@code owner}'s household once this owner is created, i.e. the existing
774	     * housemates (owners sharing the same {@code householdId}) plus {@code owner} itself.
775	     */
776	    private int countHouseholdMembers(Owner owner) {
777	        return findHousemates(owner).size() + 1;
778	    }
