289	    /**
290	     * The owner's membership points, derived on read: they start at 0, add 2 when an email is
291	     * present, add 1 when {@link #namesakeCount} is 0, add 2 for a household of 3 or more
292	     * ({@link #householdMemberCount}), and add 3 for tenure over one fiscal year (elapsed fiscal
293	     * years from {@link #registrationDate} to today; see {@link #hasTenureBonus(LocalDate)}).
294	     */
295	    @Transient
296	    public Integer getMembershipPoints() {
297	        return membershipPoints(this.email, this.namesakeCount, this.householdMemberCount,
298	            this.registrationDate);
299	    }
300	
301	    /**
302	     * The owner's numeric membership level, derived on read from {@link #getMembershipPoints()}:
303	     * level 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and 4 for 6 or more; then held down to the owner's
304	     * {@link #getMembershipLevelCap() membership level cap} when one has been assigned.
305	     */
306	    @Transient
307	    public Integer getMembershipLevel() {
308	        return capMembershipLevel(membershipLevel(getMembershipPoints()), this.membershipLevelCap);
309	    }
310	
311	    /** The membership points derived from the given factors: they start at 0, add 2 when
312	     *  {@code email} is present, add 1 when {@code namesakeCount} is 0, add 2 for a household of 3 or
313	     *  more ({@code householdMemberCount}), and add 3 for sufficient tenure (see
314	     *  {@link #hasTenureBonus(LocalDate)}). */
315	    private static int membershipPoints(String email, Integer namesakeCount,
316	            Integer householdMemberCount, LocalDate registrationDate) {
317	        int points = 0;
318	        if (email != null && !email.isBlank()) {
319	            points += 2;
320	        }
321	        if (namesakeCount != null && namesakeCount == 0) {
322	            points += 1;
323	        }
324	        if (householdMemberCount != null && householdMemberCount >= 3) {
325	            points += 2;
326	        }
327	        if (hasTenureBonus(registrationDate)) {
328	            points += 3;
329	        }
330	        return points;
331	    }
332	
333	    /** Whether the owner's tenure earns the membership tenure bonus: the elapsed fiscal years from
334	     *  {@code registrationDate} to today exceed one, i.e. the registration falls two or more fiscal
335	     *  years before the current one (fiscal years start 1 July). A null registration date earns no
336	     *  bonus. */
337	    private static boolean hasTenureBonus(LocalDate registrationDate) {
338	        return registrationDate != null
339	            && fiscalYear(LocalDate.now()) - fiscalYear(registrationDate) > 1;
340	    }
341	
342	    /**
343	     * The fiscal year (starting 1 July) that contains {@code date}, identified by the calendar year
344	     * in which that fiscal year ends: a date in July-December belongs to the fiscal year ending the
345	     * following calendar year, and a date in January-June to the fiscal year ending that same year
346	     * (e.g. 2026-09-05 -> 2027, 2026-03-01 -> 2026).
347	     */
348	    public static int fiscalYear(LocalDate date) {
349	        return date.getMonthValue() >= 7 ? date.getYear() + 1 : date.getYear();
350	    }
351	
352	    /**
353	     * The owner's fiscal year, derived on read from the (business-day-adjusted)
354	     * {@link #registrationDate} as {@code "FY<YY>"}, where YY is the last two digits of the fiscal
355	     * year (starting 1 July) that contains the registration date (e.g. a date of 2026-09-05 yields
356	     * {@code "FY27"}). Returns {@code null} when no registration date is available.
357	     */
358	    @Transient
359	    public String getFiscalYear() {
360	        if (this.registrationDate == null) {
361	            return null;
362	        }
363	        return String.format("FY%02d", fiscalYear(this.registrationDate) % 100);
364	    }
365	
366	    /** The numeric membership level (1-4) mapped from membership points: 1 for 0-1 points, 2 for
367	     *  2-3, 3 for 4-5, and 4 for 6 or more. */
368	    private static int membershipLevel(int points) {
369	        if (points >= 6) {
370	            return 4;
371	        }
372	        if (points >= 4) {
373	            return 3;
374	        }
375	        if (points >= 2) {
376	            return 2;
377	        }
378	        return 1;
379	    }
380	
381	    /** The membership {@code level} held down to {@code cap}, i.e. the smaller of the two, when a cap
382	     *  is present; the level unchanged when {@code cap} is {@code null} and no ceiling applies. */
383	    private static int capMembershipLevel(int level, Integer cap) {
384	        return cap == null ? level : Math.min(level, cap);
385	    }
386	
387	    /**
388	     * The owner's preferred contact channel, derived on read: {@code "EMAIL"} when an email is
389	     * present, otherwise {@code "PHONE"}.
390	     */
391	    @Transient
392	    public String getContactPreference() {
393	        return (this.email != null && !this.email.isBlank()) ? "EMAIL" : "PHONE";
394	    }
395	
396	    /**
397	     * The owner's age band, derived on read from the {@link #birthDate} relative to the
398	     * {@link #registrationDate}: {@code "MINOR"} when under 18, {@code "ADULT"} from 18 to 64, and
399	     * {@code "SENIOR"} at 65 or over. Returns {@code null} when no birth date (or no registration
400	     * date to measure against) is available.
401	     */
402	    @Transient
403	    public String getAgeBand() {
404	        if (this.birthDate == null || this.registrationDate == null) {
405	            return null;
406	        }
407	        int age = java.time.Period.between(this.birthDate, this.registrationDate).getYears();
408	        if (age < 18) {
409	            return "MINOR";
410	        }
411	        if (age < 65) {
412	            return "ADULT";
413	        }
414	        return "SENIOR";
415	    }
416	
417	    /**
418	     * The single Luhn check digit (0-9) computed over the decimal digits contained in the
419	     * {@link #customerCode}, derived on read.
420	     */
421	    @Transient
422	    public Integer getCheckDigit() {
423	        return luhnCheckDigit(this.customerCode);
424	    }
425	
426	    /** Region -> inclusive 4-digit postcode range {low, high}, used to derive the region from the
427	     *  postcode ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). */
428	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
429	        "NSW", new int[] {2000, 2099},
430	        "VIC", new int[] {3000, 3099},
431	        "QLD", new int[] {4000, 4099});
432	
433	    /**
434	     * The owner's region, derived on read. The postcode is preferred: a 4-digit postcode falling in a
435	     * known region's range ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}) yields
436	     * that region. When the postcode is absent or in no known range, it falls back to the fixed
437	     * city-to-region table ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}).
438	     * Returns {@code "UNKNOWN"} when neither source resolves a region.
439	     */
440	    @Transient
441	    public String getRegion() {
442	        String byPostcode = regionForPostcode(this.postcode);
443	        if (byPostcode != null) {
444	            return byPostcode;
445	        }
446	        if ("Sydney".equals(this.city)) {
447	            return "NSW";
448	        }
449	        if ("Melbourne".equals(this.city)) {
450	            return "VIC";
451	        }
452	        if ("Brisbane".equals(this.city)) {
453	            return "QLD";
454	        }
455	        return "UNKNOWN";
456	    }
457	
458	    /**
459	     * The owner's locality, derived on read from the region-and-hash {@link #getCustomerCode()
460	     * customer code}: the region segment before the first '-' of the customer code
461	     * ('<REGION>-<HASH8>'). Falls back to the owner's {@link #getRegion() region} when no customer
462	     * code has been assigned yet.
463	     */
464	    @Transient
465	    public String getLocality() {
466	        if (this.customerCode != null) {
467	            int dash = this.customerCode.indexOf('-');
468	            if (dash > 0) {
469	                return this.customerCode.substring(0, dash);
470	            }
471	        }
472	        return getRegion();
473	    }
474	
475	    /** Region -> IANA timezone name, the fixed region-to-timezone table ({@code NSW ->
476	     *  Australia/Sydney}, {@code VIC -> Australia/Melbourne}, {@code QLD -> Australia/Brisbane}). */
477	    private static final Map<String, String> REGION_TIMEZONES = Map.of(
478	        "NSW", "Australia/Sydney",
479	        "VIC", "Australia/Melbourne",
480	        "QLD", "Australia/Brisbane");
481	
482	    /**
483	     * The owner's timezone, derived on read as the IANA name for the owner's
484	     * {@link #getLocality() locality/region} via the fixed region-to-timezone table
485	     * ({@code NSW -> Australia/Sydney}, {@code VIC -> Australia/Melbourne},
486	     * {@code QLD -> Australia/Brisbane}). Returns {@code null} when the region carries no entry in
487	     * the table (e.g. {@code UNKNOWN}).
488	     */
489	    @Transient
490	    public String getTimezone() {
491	        return timezoneForRegion(getLocality());
492	    }
493	
494	    /** The IANA timezone name for {@code region} via the fixed region-to-timezone table, or
495	     *  {@code null} when the region carries no entry ({@code NSW -> Australia/Sydney},
496	     *  {@code VIC -> Australia/Melbourne}, {@code QLD -> Australia/Brisbane}). */
497	    public static String timezoneForRegion(String region) {
498	        return REGION_TIMEZONES.get(region);
499	    }
500	
501	    /** The inclusive 4-digit postcode {@code {low, high}} range for {@code region}, or {@code null} when
502	     *  the region carries no range rule (i.e. {@code UNKNOWN} or any region absent from the table:
503	     *  {@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). */
504	    public static int[] postcodeRangeForRegion(String region) {
505	        return REGION_POSTCODE_RANGES.get(region);
506	    }
507	
508	    /** The region whose postcode range contains {@code postcode}, or {@code null} when the postcode is
509	     *  absent, not a 4-digit value, or in no known range. */
510	    private static String regionForPostcode(String postcode) {
511	        if (postcode == null || !postcode.matches("^[0-9]{4}$")) {
512	            return null;
513	        }
514	        int value = Integer.parseInt(postcode);
515	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
516	            int[] range = entry.getValue();
517	            if (value >= range[0] && value <= range[1]) {
518	                return entry.getKey();
519	            }
520	        }
521	        return null;
522	    }
523	
524	    /** Telephone country code -> the national-number length it requires ({@code +61} Australia => 9
525	     *  digits, {@code +1} NANP => 10), used to derive telephone values from the stored E.164 number.
526	     *  The country codes here carry no conflicting prefixes ({@code +61} does not start with
527	     *  {@code +1}), so a number matches at most one. */
528	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = Map.of(
529	        "+61", 9, "+1", 10);
530	
531	    /**
532	     * The stored E.164 {@link #telephone} formatted for humans, derived on read: the country code, a
533	     * space, then the national digits grouped in threes (e.g. {@code "+61 412 345 678"}). Falls back
534	     * to the raw value when it is {@code null} or begins with no recognised country code.
535	     */
536	    @Transient
537	    public String getTelephoneDisplay() {
538	        if (this.telephone == null) {
539	            return null;
540	        }
541	        String countryCode = countryCodeOf(this.telephone);
542	        if (countryCode == null) {
543	            return this.telephone;
544	        }
545	        String national = this.telephone.substring(countryCode.length());
546	        StringBuilder grouped = new StringBuilder(countryCode);
547	        for (int i = 0; i < national.length(); i++) {
548	            if (i % 3 == 0) {
549	                grouped.append(' ');
550	            }
551	            grouped.append(national.charAt(i));
552	        }
553	        return grouped.toString();
554	    }
555	
556	    /** The recognised telephone country code that {@code telephone} begins with (e.g. {@code "+61"}),
557	     *  or {@code null} when it is {@code null} or begins with no recognised country code. */
558	    public static String countryCodeOf(String telephone) {
559	        if (telephone == null) {
560	            return null;
561	        }
562	        for (String countryCode : NATIONAL_NUMBER_LENGTHS.keySet()) {
563	            if (telephone.startsWith(countryCode)) {
564	                return countryCode;
565	            }
566	        }
567	        return null;
568	    }
569	
570	    /** The national-number length required for {@code countryCode}, or {@code null} when the country
571	     *  code carries no length rule (i.e. any code absent from the table: {@code +61 => 9},
572	     *  {@code +1 => 10}). */
573	    public static Integer nationalNumberLength(String countryCode) {
574	        return NATIONAL_NUMBER_LENGTHS.get(countryCode);
575	    }
576	
577	    /** The single Luhn check digit (0-9) over the decimal digits contained in {@code value}, scanning
578	     *  right to left and doubling every second digit; non-digit characters are ignored and a null or
579	     *  digit-free value yields {@code 0}. */
580	    private static int luhnCheckDigit(String value) {
581	        int sum = 0;
582	        boolean doubling = true;
583	        for (int i = (value == null ? 0 : value.length()) - 1; i >= 0; i--) {
584	            char c = value.charAt(i);
585	            if (c < '0' || c > '9') {
586	                continue;
587	            }
588	            int digit = c - '0';
589	            if (doubling) {
590	                digit *= 2;
591	                if (digit > 9) {
592	                    digit -= 9;
593	                }
594	            }
595	            sum += digit;
596	            doubling = !doubling;
597	        }
598	        return (10 - (sum % 10)) % 10;
599	    }
600	
601	    protected Set<Pet> getPetsInternal() {
602	        if (this.pets == null) {
603	            this.pets = new HashSet<>();
604	        }
605	        return this.pets;
606	    }
607	
608	    protected void setPetsInternal(Set<Pet> pets) {
609	        this.pets = pets;
610	    }
611	
612	    public List<Pet> getPets() {
613	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
614	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
615	        return Collections.unmodifiableList(sortedPets);
616	    }
617	
618	    public void setPets(List<Pet> pets) {
619	        this.pets = new HashSet<>(pets);
620	    }
621	
622	    public void addPet(Pet pet) {
623	        getPetsInternal().add(pet);
624	        pet.setOwner(this);
625	    }
626	
627	    /**
628	     * Return the Pet with the given name, or null if none found for this Owner.
629	     *
630	     * @param name to test
631	     * @return true if pet name is already in use
632	     */
633	    public Pet getPet(String name) {
634	        return getPet(name, false);
635	    }
636	
637	    /**
638	     * Return the Pet with the given name, or null if none found for this Owner.
639	     *
640	     * @param name to test
641	     * @return true if pet name is already in use
642	     */
643	    public Pet getPet(String name, boolean ignoreNew) {
644	        name = name.toLowerCase();
645	        for (Pet pet : getPetsInternal()) {
646	            if (!ignoreNew || !pet.isNew()) {
647	                String compName = pet.getName();
648	                compName = compName.toLowerCase();
649	                if (compName.equals(name)) {
650	                    return pet;
651	                }
652	            }
653	        }
654	        return null;
655	    }
656	
657	    public Pet getPet(Integer petId) {
658	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
659	    }
660	
661	    @Override
662	    public String toString() {
663	        return new ToStringCreator(this)
664	
665	            .append("id", this.getId())
666	            .append("new", this.isNew())
667	            .append("lastName", this.getLastName())
668	            .append("firstName", this.getFirstName())
669	            .append("address", this.address)
670	            .append("city", this.city)
671	            .append("telephone", this.telephone)
672	            .toString();
673	    }
674	}
