692	     * The single derived key all duplicate detection flows through, formed from the owner's
693	     * already-normalized fields as {@code normalizedTelephone + '|' + (email or empty) + '|' +
694	     * (householdId or empty)}. It is computed at the create-time identity gate, before the household
695	     * id is derived, so the household segment is empty at that point. Because the telephone is part
696	     * of the key, two owners in the same household with different telephones resolve to different
697	     * keys and are both allowed.
698	     */
699	    private static String identityKey(Owner owner) {
700	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
701	        String email = owner.getEmail() == null ? "" : owner.getEmail();
702	        String household = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
703	        return telephone + "|" + email + "|" + household;
704	    }
