706	    /**
707	     * Whether {@code owner}'s whole {@link #identityKey} equals an existing owner's, which is the sole
708	     * duplicate condition: the previously separate telephone, email and household checks are now all
709	     * expressed through this one key, so only an exact full-key match is a duplicate and a create that
710	     * trips it is rejected with {@code 409 CONFLICT}.
711	     */
712	    private boolean isDuplicate(Owner owner) {
713	        String key = owner.getIdentityKey();
714	        return this.clinicService.findAllOwners().stream()
715	            .filter(existing -> !existing.isDeleted())
716	            .map(Owner::getIdentityKey)
717	            .filter(existing -> existing != null)
718	            .anyMatch(key::equals);
